# bootstrap-pfta.ps1
# H0008 Product-3 (PFTA) â€” write full codebase into existing scaffold
# Runs in PowerShell 5+ / 7+ on Windows
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-TextFileNoBom {
  param(
    [Parameter(Mandatory=$true)][string]$Path,
    [Parameter(Mandatory=$true)][string]$Content
  )
  $full = [System.IO.Path]::GetFullPath($Path)
  $dir = [System.IO.Path]::GetDirectoryName($full)
  if (-not [string]::IsNullOrWhiteSpace($dir) -and -not (Test-Path $dir)) {
    New-Item -ItemType Directory -Path $dir | Out-Null
  }
  $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($full, $Content, $utf8NoBom)
}

function Ensure-InPftaRoot {
  $cwd = (Get-Location).Path
  $contracts = Join-Path $cwd "contracts"
  $scripts   = Join-Path $cwd "scripts"
  $tests     = Join-Path $cwd "test"

  if (-not (Test-Path $contracts) -or -not (Test-Path $scripts) -or -not (Test-Path $tests)) {
    throw "Not in PFTA root. Expected folders 'contracts', 'scripts', 'test' in: $cwd"
  }
}

function Update-PackageJsonScripts {
  param(
    [Parameter(Mandatory=$true)][string]$Path
  )

  if (-not (Test-Path $Path)) {
    throw "package.json not found at $Path"
  }

  $json = Get-Content $Path -Raw | ConvertFrom-Json
  if ($null -eq $json.scripts) {
    $json | Add-Member -NotePropertyName scripts -NotePropertyValue (@{})
  }

  # Merge/overwrite only our scripts (do not delete other keys)
  $json.scripts.test        = "hardhat test"
  $json.scripts.compile     = "hardhat compile"
  $json.scripts.clean       = "hardhat clean"
  $json.scripts.node        = "hardhat node"
  $json.scripts."deploy:local" = "hardhat run scripts/deploy_local.js --network hardhat"
  $json.scripts."seed:local"   = "hardhat run scripts/seed_treasury.js --network hardhat"
  $json.scripts."run:payment"  = "hardhat run scripts/run_payment.js --network hardhat"

  # Make license MIT (DoD requirement is an OS license file; package.json helps too)
  $json.license = "MIT"

  $out = $json | ConvertTo-Json -Depth 20
  Write-TextFileNoBom -Path $Path -Content $out
}

